'use strict';

/**
 * Стрим для yandex-logger, позволяющий логировать в Qloud-совместимом формате.
 *
 * @param {YandexLoggerDefaultStreamConfig} [config]
 * @returns {Object}
 */
module.exports = config => {
    config = config || {};

    // Если в Qloud не включен JSON логгер, то логируем просто строками
    if (process.env.QLOUD_LOGGER_STDERR_PARSER === 'json') {
        return require('./qloud')(config.qloud);
    }

    return require('./line')(config.line);
};

/**
 * @typedef {Object} YandexLoggerDefaultStreamConfig
 * @property {YandexLoggerLineStreamConfig} [line]
 * @property {YandexLoggerQloudStreamConfig} [qloud]
 */
